INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", 870, "", 103411, 1034501039, "", 1034501, 13, "", "", "");
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "わあ……素敵なケーキね！\nえ？　キミが作ったの？\nすごいじゃない！", 0, 103411, 1034501040, "", 1034501, 11, 1, 0, 4);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1034501041, "", 1034501, 91, "", "", "");
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, "vo_adv_1034501_001", "", "vo_adv_1034501", 1034501042, "", 1034501, 21, "", "", 0);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "麦しゅわに合わないかも……って、\nそんな気を使わなくていいわよ。\nだって、今日は飲むつもりはないもの。", 0, 103411, 1034501043, "", 1034501, 11, 1, 0, 6);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1034501044, "", 1034501, 91, "", "", "");
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, "vo_adv_1034501_002", "", "vo_adv_1034501", 1034501045, "", 1034501, 21, "", "", 0);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "なんでって、それは……\nキミがお祝いに来てくれるかも、\nなんて思ってたから……", 0, 103411, 1034501046, "", 1034501, 11, 1, 0, 5);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1034501047, "", 1034501, 91, "", "", "");
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, "vo_adv_1034501_003", "", "vo_adv_1034501", 1034501048, "", 1034501, 21, "", "", 0);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "だから、今日は麦しゅわは封印よ。\n麦しゅわもありの大人な誕生日は、\nキミが大人になってから……ね？", 0, 103411, 1034501049, "", 1034501, 11, 1, 0, 5);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1034501050, "", 1034501, 91, "", "", "");
