INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "たい焼きの他にケーキまで\n作れるにゃんて……\nキミって意外と料理上手にゃ？", 0, 104611, 1046501043, "", 1046501, 11, 1, 0, 6);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1046501044, "", 1046501, 91, "", "", "");
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, "vo_adv_1046501_002", "", "vo_adv_1046501", 1046501045, "", 1046501, 21, "", "", 0);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (1, "にゃにゃ……？\nキミのケーキを見てたら\n新しいたい焼きのアイデアが\nどんどん湧いてきたにゃ！", 0, 104611, 1046501046, "", 1046501, 11, 1, 0, 6);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 0, 1046501047, "", 1046501, 91, "", "", "");
